for a0 in 0..16:
    for a1 in 0..128:
        for a2 in 0..1024:
            in0 = load x0[0, 0, a2]
            in1 = load x1[128 * a0 + a1, a2]
            f32 v0 = in0 * in1
            acc0 <- add(acc0, v0) over a2
        f16 v1 = acc0
        f32 v2 = copy(v1)
        to[0, 0, a0, a1] = v2
